    private ProductSeedFile.Prepared prepare(byte[] bytes,String hash)throws Exception{return ProductSeedFile.prepare(new ByteArrayInputStream(bytes),root,hash,null,null);}
    private JSONObject proof(ProductSeedFile.Prepared p)throws Exception{JSONObject m=p.manifest(),proof=new JSONObject().put("verified",true).put("sha256",p.sha256()).put("redactions",new JSONArray());for(String k:new String[]{"packageId","libraryId","epoch","checkpoint","watermark","policy"})proof.put(k,m.get(k));return proof;}
    private JSONObject asset(String name)throws Exception{try(InputStream in=getTargetContext().getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}}
    private byte[] zip(String[] names,byte[][] contents)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(out)){for(int i=0;i<names.length;i++){zip.putNextEntry(new ZipEntry(names[i]));zip.write(contents[i]);zip.closeEntry();}}return out.toByteArray();}
    private void replace(byte[] bytes,String from,String to){byte[] a=from.getBytes(StandardCharsets.UTF_8),b=to.getBytes(StandardCharsets.UTF_8);for(int i=0;i<=bytes.length-a.length;i++){boolean same=true;for(int n=0;n<a.length;n++)if(bytes[i+n]!=a[n])same=false;if(same)System.arraycopy(b,0,bytes,i,b.length);}}
